+#ifndef BITCOIN_INDEX_TXOSCRIPTINDEX_KEY_H
+#define BITCOIN_INDEX_TXOSCRIPTINDEX_KEY_H
+
+#include <consensus/consensus.h>
+#include <crypto/siphash.h>
+#include <index/ordered_varint.h>
